"""Generate an offline interactive dashboard from measured results."""
import json


def render(data, destination):
    page = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pharmacy Claims Operations</title><style>
body{font-family:system-ui,sans-serif;margin:0;background:#f1f5f7;color:#183b4e}main{max-width:1100px;margin:auto;padding:30px}header{background:#183b4e;color:white;border-radius:16px;padding:30px}h1{font-size:34px}h2{font-size:21px}p{line-height:1.6}.notice{background:#fff2ce;padding:16px;margin:20px 0;border-left:4px solid #c58c24}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card,section{background:white;padding:22px;border-radius:12px;border:1px solid #d8e3e8;margin:12px 0}.value{font-size:30px;font-weight:700;margin-top:10px}.muted{color:#587080;font-size:13px}select{padding:9px;font:inherit;border-radius:6px}table{border-collapse:collapse;width:100%}th,td{padding:12px;text-align:left;border-bottom:1px solid #d8e3e8}.track{background:#edf1f4}.bar{background:#009b84;height:22px;border-radius:4px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}footer{padding:20px;font-size:13px}@media(max-width:700px){.cards,.grid{grid-template-columns:1fr}main{padding:12px}table{font-size:12px}th,td{padding:6px}}</style>
<main><header><div>PORTFOLIO LAB · PYTHON / SQL / MACHINE LEARNING</div><h1>Pharmacy Claims Operations</h1><p>Prioritizing synthetic rejected claims for operational follow-up.</p></header><div class="notice"><strong>Synthetic data only.</strong> No CVS, Caremark, patient, or real pharmacy claims data. Simulator results do not establish clinical or business impact.</div><div class="cards" id="cards"></div>
<section><h2>Review capacity explorer</h2><p>Held-out temporal test cohort. Model compared with a rejection-reason baseline learned on training data.</p><label for="capacity">Review capacity </label><select id="capacity"><option>5%</option><option>10%</option><option selected>20%</option><option>30%</option><option>50%</option></select><div id="ranking"></div><p class="muted">Ranks the entire test cohort; ties retain submission order. Captured cases are identified, not prevented. This is not a daily queue or an intervention-effect estimate.</p></section>
<section><h2>Rejection workflow explorer</h2><label for="reason">Rejection reason </label><select id="reason"></select><div id="workflow"></div><p class="muted">Full simulated dataset at the snapshot. Seven-day rates use mature episodes only. Mean hours excludes unresolved cases and is not an unbiased time-to-resolution estimate.</p></section>
<section><h2>Model evaluation</h2><p id="selected"></p><table><thead><tr><th>Model</th><th>ROC-AUC</th><th>Average precision</th><th>Brier ↓</th></tr></thead><tbody id="models"></tbody></table><p id="ci" class="muted"></p></section>
<div class="grid"><section><h2>Monitoring simulation</h2><div id="monitor"></div><p class="muted">PSI threshold 0.20 is illustrative. A distribution change does not necessarily mean performance has deteriorated.</p></section><section><h2>Temporal partitions</h2><div id="splits"></div><p class="muted">Seven-day gaps allow outcomes to mature. Features are available at initial rejection. Resolution timestamp is label-only.</p></section></div>
<section><h2>Operational interpretation</h2><ul><li>Investigate recurring rejection reasons with pharmacy operations experts.</li><li>Compare prioritization methods at realistic staff capacity before planning a pilot.</li><li>Before real use: validate real longitudinal data, assess subgroup performance, establish urgent-case handling, and measure prospective outcomes.</li></ul></section><footer>Source: reproducible synthetic generator · Seed 42 for committed run · Snapshot 2025-08-29 · See metrics.json, model card, and SQL for definitions.</footer></main>
<script>const D=__DATA__;const pct=x=>(x*100).toFixed(1)+'%';const num=x=>x.toLocaleString('en-US');const label=x=>x.replaceAll('_',' ');
document.getElementById('cards').innerHTML=[['Synthetic episodes',num(D.episodes)],['Initial rejection rate',pct(D.initial_rejection_rate)],['Test rejected episodes',num(D.splits.test.n)],['Test ROC-AUC',D.test.selected_model.roc_auc.toFixed(3)]].map(([k,v])=>`<div class="card"><span class="muted">${k}</span><div class="value">${v}</div></div>`).join('');
const cap=document.getElementById('capacity');function updateCapacity(){const c=D.capacity[cap.selectedIndex];document.getElementById('ranking').innerHTML=[['Selected model',c.model],['Reason baseline',c.reason_baseline]].map(([k,v])=>`<h3>${k}: ${pct(v.recall)} captured</h3><div class="track"><div class="bar" style="width:${v.recall*100}%"></div></div><p>${num(v.captured)} of ${num(v.total_unresolved)} unresolved cases in ${num(v.reviewed)} reviews · Precision ${pct(v.precision)}</p>`).join('');}cap.addEventListener('change',updateCapacity);updateCapacity();
const reason=document.getElementById('reason');reason.innerHTML=D.operations.map(r=>`<option>${label(r.reject_reason)}</option>`).join('');function updateReason(){const r=D.operations[reason.selectedIndex];document.getElementById('workflow').innerHTML=`<p><strong>${num(r.rejected_episodes)}</strong> rejected episodes · <strong>${pct(r.unresolved_7d_rate)}</strong> unresolved at seven days among ${num(r.mature_episodes)} mature episodes.</p><p>${num(r.resolved_by_snapshot)} resolved by snapshot · ${r.mean_hours_among_resolved.toFixed(1)} mean hours among resolved cases.</p>`;}reason.addEventListener('change',updateReason);updateReason();
document.getElementById('selected').textContent='Selected: '+label(D.selected_model)+'. '+D.selection+'.';document.getElementById('models').innerHTML=Object.entries(D.test).map(([k,v])=>`<tr><td>${label(k)}</td><td>${v.roc_auc.toFixed(3)}</td><td>${v.average_precision.toFixed(3)}</td><td>${v.brier_score.toFixed(3)}</td></tr>`).join('');document.getElementById('ci').textContent='Model ROC-AUC bootstrap 95% interval: '+D.test_roc_auc_bootstrap_95ci.map(x=>x.toFixed(3)).join('–')+'. '+D.bootstrap_note+'.';
const m=D.monitoring;document.getElementById('monitor').innerHTML=`<p>Test score PSI: <strong>${m.test_score_psi.toFixed(3)}</strong> — ${m.test_alert?'ALERT':'below threshold'}</p><p>Stress score PSI: <strong>${m.stress_score_psi.toFixed(3)}</strong> — ${m.stress_alert?'ALERT':'below threshold'}</p><p>${m.stress_scenario}</p>`;document.getElementById('splits').innerHTML=Object.entries(D.splits).map(([k,v])=>`<p><strong>${label(k)}</strong>: ${num(v.n)} episodes<br><span class="muted">${v.start.slice(0,10)} to ${v.end.slice(0,10)}</span></p>`).join('');</script></html>'''
    destination.write_text(page.replace('__DATA__', json.dumps(data, allow_nan=False)))
